package app.cryptoresearch.mobile;
import android.content.Context;import android.content.res.Configuration;import android.view.*;import android.app.AlertDialog;import android.widget.*;import org.junit.*;import static org.junit.Assert.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import org.robolectric.shadows.ShadowAlertDialog;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28,qualifiers="w320dp-h640dp-notnight") @LooperMode(LooperMode.Mode.PAUSED)
public class OneUiTests {
 @After public void cleanup(){RuntimeEnvironment.getApplication().getSharedPreferences(OneUi.PREF,0).edit().clear().commit();}
 double channel(int c){double x=c/255.;return x<=.04045?x/12.92:Math.pow((x+.055)/1.055,2.4);}
 double luminance(int color){return .2126*channel(android.graphics.Color.red(color))+.7152*channel(android.graphics.Color.green(color))+.0722*channel(android.graphics.Color.blue(color));}
 double contrast(int a,int b){double x=luminance(a),y=luminance(b);return (Math.max(x,y)+.05)/(Math.min(x,y)+.05);}
 @Test public void readableLightAndDarkPalettes(){Context base=RuntimeEnvironment.getApplication();for(int night:new int[]{Configuration.UI_MODE_NIGHT_NO,Configuration.UI_MODE_NIGHT_YES}){Configuration config=new Configuration(base.getResources().getConfiguration());config.uiMode=(config.uiMode&~Configuration.UI_MODE_NIGHT_MASK)|night;Context c=base.createConfigurationContext(config);assertTrue(contrast(OneUi.ink(c),OneUi.surface(c))>=4.5);assertTrue(contrast(OneUi.muted(c),OneUi.surface(c))>=4.5);assertTrue(contrast(OneUi.blue(c),OneUi.tonal(c))>=4.5);}}
 @Test public void navigationAndScrollableViewingArea(){var controller=Robolectric.buildActivity(MainActivity.class).create();MainActivity a=controller.get();assertEquals(4,a.nav.getChildCount());assertTrue(a.body.getChildAt(0) instanceof LinearLayout);for(int i=0;i<4;i++){View item=a.nav.getChildAt(i);assertTrue(item.getMinimumHeight()>=OneUi.dp(a,48));item.performClick();assertEquals(i,a.tab);assertTrue(a.nav.getChildAt(i).isSelected());}controller.destroy();}
 @Test public void appearanceRecreationPreservesPaperAccount(){var controller=Robolectric.buildActivity(MainActivity.class).create().start().resume();MainActivity a=controller.get();a.paper=new StrategyCore.Live("BTC",1000000,5,5);a.paper.engine.cash=900000;a.paper.engine.qty=2;a.strategyReport=a.paper.engine.report();a.tab=2;controller.recreate();MainActivity restored=controller.get();assertNotNull(restored.paper);assertEquals(900000,restored.paper.engine.cash,0);assertEquals(2,restored.paper.engine.qty,0);assertNotNull(restored.strategyReport);assertEquals(2,restored.tab);controller.pause().stop().destroy();}
 @Test public void confirmDialogRequiresExplicitStart(){var controller=Robolectric.buildActivity(MainActivity.class).create();MainActivity a=controller.get();int[] called={0};OneUi.confirm(a,"새 계좌","잔고 초기화",()->called[0]++);AlertDialog dialog=ShadowAlertDialog.getLatestAlertDialog();dialog.getButton(AlertDialog.BUTTON_NEGATIVE).performClick();org.robolectric.Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();assertEquals(0,called[0]);OneUi.confirm(a,"새 계좌","잔고 초기화",()->called[0]++);ShadowAlertDialog.getLatestAlertDialog().getButton(AlertDialog.BUTTON_POSITIVE).performClick();org.robolectric.Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();assertEquals(1,called[0]);controller.destroy();}
 @Test public void searchEmptyStateAndDarkPreference(){var controller=Robolectric.buildActivity(MainActivity.class).create();MainActivity a=controller.get();a.search="does-not-exist";a.renderRows();LinearLayout rows=a.body.findViewWithTag("rows");assertEquals(1,rows.getChildCount());assertTrue(((TextView)rows.getChildAt(0)).getText().toString().contains("검색 결과"));controller.destroy();RuntimeEnvironment.getApplication().getSharedPreferences(OneUi.PREF,0).edit().putString(OneUi.MODE,"dark").commit();var dark=Robolectric.buildActivity(BackgroundActivity.class).create();assertTrue(OneUi.dark(dark.get()));dark.destroy();}
}
